import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
import {rateFigure,catalystFigure} from './kinetic-figures.js?v=20261023-physicscomplete01';
export function showKinetics(kind='graphs',t=null,a={},reveal=false){if(kind==='catalyst'){renderDiagram('A different pathway','Same reactants · same products',catalystFigure({peak:t?.id==='path'?(['65','90','100'].includes(a.peak)?Number(a.peak):90):65})+'<p class="diagram-caption">Symbolic relative energy levels, not a time graph or molecular mechanism.</p>','CATALYST COMPARISON · SHARED ENDPOINTS');return;}const mode=t?.id||kind;renderDiagram(mode==='tangent'?'Follow the local direction':mode==='plot'?'Place each reading':'Rate and amount differ',mode==='tangent'?'Tangent fixed at30 s':'Quantity versus time',rateFigure({kind:mode==='plot'?'rate-plot':mode==='tangent'?'rate-tangent':'rate-compare',plot:a,tilt:Number(a.tilt??0),training:true})+'<p class="diagram-caption">'+(mode==='plot'?'Guided point positions; independent freehand axes and curve drawing remain separate.':mode==='tangent'?'The line pivots at one fixed contact point. Match its direction to the curve.':'Illustrative smooth runs; solid A and dashed B use the same final quantity.')+'</p>',reveal?'GRAPH REASONING CHECKED':'ILLUSTRATIVE GRAPH · NOT EXPERIMENTAL DATA');}
